import{_ as s,c as i,o as a,ag as n}from"./chunks/framework.B-XtCDNB.js";const k=JSON.parse('{"title":"Concurrency, IPC, and system interfaces","description":"Concurrency, IPC, and system interfaces Concurrency Concurrency in a computer program is running multiple, independent tasks within a given time frame. Physically this can be completed on a single...","frontmatter":{},"headers":[],"relativePath":"genie/introduction/06-concurrency-and-systems.md","filePath":"genie/introduction/06-concurrency-and-systems.md","lastUpdated":1786127789000}'),t={name:"genie/introduction/06-concurrency-and-systems.md"};function l(r,e,h,o,p,d){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="concurrency-ipc-and-system-interfaces" tabindex="-1">Concurrency, IPC, and system interfaces <a class="header-anchor" href="#concurrency-ipc-and-system-interfaces" aria-label="Permalink to &quot;Concurrency, IPC, and system interfaces&quot;">​</a></h1><h2 id="concurrency" tabindex="-1">Concurrency <a class="header-anchor" href="#concurrency" aria-label="Permalink to &quot;Concurrency&quot;">​</a></h2><p>Concurrency in a computer program is running multiple, independent tasks within a given time frame. Physically this can be completed on a single processor, but can also be completed on multiple processors in parallel. Genie makes use of GLib&#39;s concurrency functions to implement this.</p><h3 id="glib-s-event-loop-gmaincontext" tabindex="-1">GLib&#39;s Event Loop - GMainContext <a class="header-anchor" href="#glib-s-event-loop-gmaincontext" aria-label="Permalink to &quot;GLib&#39;s Event Loop - GMainContext&quot;">​</a></h3><p><code>GMainContext</code> is usually wrapped in a higher level function, for example GLib&#39;s <code>MainLoop</code> or GTK&#39;s <code>MainLoop</code>.</p><p>GLib&#39;s event loop is unrelated to Genie&#39;s <code>event</code> keyword. The <code>event</code> keyword relates to synchronous communication between objects.</p><h3 id="asynchronous-methods" tabindex="-1">Asynchronous Methods <a class="header-anchor" href="#asynchronous-methods" aria-label="Permalink to &quot;Asynchronous Methods&quot;">​</a></h3><p>Asynchronous methods are methods whose execution can be paused and resumed under the control of the programmer. They are often used in the main thread of an application where a method needs to wait for an external slow task to complete, but must not stop other processing from happening. When the method has to wait, it gives control of the CPU back to its caller (i.e. it yields), but it arranges to be called back to resume execution when data becomes ready.</p><p>Asynchronous methods are normally used with a GLib main loop running, because idle callbacks are used to handle some of the internal callbacks.</p><p>Async methods in Genie use the GIO library to handle the callbacks, so must be built with the <code>--pkg=gio-2.0</code> option.</p><p>An asynchronous method is defined with the <code>async</code> keyword. For example:</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> display_jpeg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fname : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Some code to load JPEG in a background thread here and display it when loaded</span></span></code></pre></div><p>or</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch_webpage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">out</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> text : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> raises</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IOError</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Some code to fetch a webpage asynchronously and when ready return the</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // HTTP status code and put the page contents in &#39;text&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    text = result</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> status</span></span></code></pre></div><p>The method may take arguments and return a value like any other method. It may use a <code>yield</code> statement at any time to give control of the CPU back to its caller.</p><p>An async method is called like that:</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">display_jpeg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;test.jpg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>or</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">display_jpeg.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">begin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;test.jpg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>These forms are equivalent and start the async method with the given arguments.</p><p>When an asynchronous method starts running, it takes control of the CPU until it reaches its first <code>yield</code> statement, at which point it returns to the caller. When the method is resumed, it continues execution immediately after that <code>yield</code> statement.</p><p>A common way of using <code>yield</code> is when calling another asynchronous method, for example:</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">yield</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> display_jpeg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fname)</span></span></code></pre></div><p>or</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">text : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> status = </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">yield</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch_webpage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">out</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> text)</span></span></code></pre></div><p>In both cases, the calling method gives up control of the CPU and does not resume until the called method completes. The <code>yield</code> statement automatically registers a callback with the called method to make sure that the caller resumes correctly.</p><h2 id="inter-process-communication" tabindex="-1">Inter-Process Communication <a class="header-anchor" href="#inter-process-communication" aria-label="Permalink to &quot;Inter-Process Communication&quot;">​</a></h2><h3 id="gvariant" tabindex="-1">GVariant <a class="header-anchor" href="#gvariant" aria-label="Permalink to &quot;GVariant&quot;">​</a></h3><p>The Vala compiler contains a module to generate <a href="https://valadoc.org/glib-2.0/GLib.Variant" target="_blank" rel="noreferrer"><code>GVariant</code></a>. This is used in Genie by casting to <code>Variant</code>. <code>GVariant</code> is used by GLib libraries for serialization and deserialization, for example in D-Bus APIs and <code>GSettings</code>.</p><h3 id="d-bus" tabindex="-1">D-Bus <a class="header-anchor" href="#d-bus" aria-label="Permalink to &quot;D-Bus&quot;">​</a></h3><p>The <code>[DBus]</code> attribute makes using the GDBus implementation of D-Bus easy in Genie.</p><h3 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h3><p>GLib has functions to access <a href="https://en.wikipedia.org/wiki/Environment_variable" target="_blank" rel="noreferrer">environment variables</a>. These functions are cross-platform and work on Windows and POSIX environments, such as Linux and macOS. They are bound in Vala within the <a href="https://valadoc.org/glib-2.0/GLib.Environment.html" target="_blank" rel="noreferrer"><code>GLib.Environment</code></a> namespace. The following Genie code example lists all the variables in its environment using a string template to format the output:</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">init</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> all_variables = </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">list_variables</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> item </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> all_variables</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$(item)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$(Environment.get_variable(item))</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span></code></pre></div><p>POSIX systems have the <code>PWD</code> environment variable set when the program is run from a shell. This variable contains the present working directory:</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">init</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@&quot;Present working directory: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$(Environment.get_variable( &quot;PWD&quot; ))</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span></code></pre></div><p>The GLib function to retrieve a variable&#39;s value returns <code>null</code> if the variable is unknown. In Genie a null check would be needed. In this next example an empty string is used if there is no value:</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">init</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value = </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get_variable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ENVIRONMENT_VARIABLE_THAT_DOES_NOT_EXIST&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value == </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        value = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Environment variable value: &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> + value )</span></span></code></pre></div><h3 id="running-external-programs" tabindex="-1">Running External Programs <a class="header-anchor" href="#running-external-programs" aria-label="Permalink to &quot;Running External Programs&quot;">​</a></h3><p>Use <a href="https://valadoc.org/gio-2.0/GLib.Subprocess.html" target="_blank" rel="noreferrer"><code>GLib.Subprocess</code></a>. For low-level control use <a href="https://valadoc.org/gio-2.0/GLib.SubprocessLauncher.html" target="_blank" rel="noreferrer"><code>GLib.SubprocessLauncher</code></a>. These APIs are both part of GIO so you will need to compile with <code>--pkg gio-2.0</code>.</p><h2 id="pipes" tabindex="-1">Pipes <a class="header-anchor" href="#pipes" aria-label="Permalink to &quot;Pipes&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">TODO</p><p>Add info on pipes</p></div><h2 id="handling-c-posix-system-signals" tabindex="-1">Handling C/POSIX System Signals <a class="header-anchor" href="#handling-c-posix-system-signals" aria-label="Permalink to &quot;Handling C/POSIX System Signals&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">TODO</p><p>Add info on andling C/POSIX System Signals</p></div><h2 id="user-interfaces" tabindex="-1">User Interfaces <a class="header-anchor" href="#user-interfaces" aria-label="Permalink to &quot;User Interfaces&quot;">​</a></h2><h3 id="command-line-interfaces" tabindex="-1">Command Line Interfaces <a class="header-anchor" href="#command-line-interfaces" aria-label="Permalink to &quot;Command Line Interfaces&quot;">​</a></h3><p>Use GLib&#39;s <a href="https://valadoc.org/glib-2.0/GLib.OptionContext" target="_blank" rel="noreferrer"><code>OptionContext</code></a> for option parsing.</p><h3 id="graphical-user-interfaces" tabindex="-1">Graphical User Interfaces <a class="header-anchor" href="#graphical-user-interfaces" aria-label="Permalink to &quot;Graphical User Interfaces&quot;">​</a></h3><p>Genie has excellent bindings to GTK. This includes the <code>[GtkTemplate]</code> attribute for accessing windows and widgets from a <code>GResource</code> compiled into a program.</p><h3 id="voice-user-interfaces" tabindex="-1">Voice User Interfaces <a class="header-anchor" href="#voice-user-interfaces" aria-label="Permalink to &quot;Voice User Interfaces&quot;">​</a></h3><p>Genie has excellent bindings to <a href="https://gstreamer.freedesktop.org/" target="_blank" rel="noreferrer">GStreamer</a>.</p>`,51)])])}const g=s(t,[["render",l]]);export{k as __pageData,g as default};
